--
-- Table structure for table `queries_complaints`
--

DROP TABLE IF EXISTS `queries_complaints`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `queries_complaints` (
  `qc_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `qc_firstname` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `qc_lastname` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `qc_phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qc_email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qc_anonymous` tinyint(1) NOT NULL,
  `qc_description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `qc_result` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qc_status_document` enum('Recibida','En revisión inicial','En análisis','En proceso de resolución','Resuelta','Cerrada') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Recibida',
  `qc_type` enum('Queja','Denuncia') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Queja',
  `qc_idprocedure` bigint unsigned DEFAULT NULL,
  `qc_idinstitution` bigint unsigned DEFAULT NULL,
  `qc_access` int DEFAULT NULL,
  `qc_percentage` tinyint unsigned NOT NULL DEFAULT '0',
  `qc_created_by` bigint unsigned DEFAULT NULL,
  `qc_updated_by` bigint unsigned DEFAULT NULL,
  `qc_created_at` timestamp NULL DEFAULT NULL,
  `qc_updated_at` timestamp NULL DEFAULT NULL,
  `qc_status` tinyint NOT NULL DEFAULT '1',
  `qc_waiting_response` tinyint DEFAULT '0',
  `qc_is_query` tinyint DEFAULT '0',
  PRIMARY KEY (`qc_id`),
  KEY `queries_complaints_qc_idprocedure_foreign` (`qc_idprocedure`),
  KEY `queries_complaints_qc_idinstitution_foreign` (`qc_idinstitution`),
  KEY `queries_complaints_qc_created_by_foreign` (`qc_created_by`),
  KEY `queries_complaints_qc_updated_by_foreign` (`qc_updated_by`),
  KEY `queries_complaints_qc_phone_index` (`qc_phone`),
  KEY `queries_complaints_qc_email_index` (`qc_email`),
  CONSTRAINT `queries_complaints_qc_created_by_foreign` FOREIGN KEY (`qc_created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `queries_complaints_qc_idinstitution_foreign` FOREIGN KEY (`qc_idinstitution`) REFERENCES `institutions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `queries_complaints_qc_idprocedure_foreign` FOREIGN KEY (`qc_idprocedure`) REFERENCES `procedures` (`id`) ON DELETE SET NULL,
  CONSTRAINT `queries_complaints_qc_updated_by_foreign` FOREIGN KEY (`qc_updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

